with release_notes (ordinal, title, summary) as (
  values
    (1, 'shortbits.net 2.0',
      'The next major collection of Bits: separate personal and professional experiences, a richer BITS OS desktop, expanded publishing and Admin tools, real hardware and NAS telemetry, creator recommendations, deeper themes and boot displays, restored games, and faster, more reliable delivery. The following 2.0 entries catch up on features and improvements not covered by the 1.x changelog.'),
    (2, 'shortbits.net 2.0 - Professional profile and resume',
      'Added a profile chooser at the home page, a dedicated professional profile, and shared Admin-managed career data across the professional page and CAREER.SYS. Work history supports date ranges, durations, bullet summaries, and technology tags; education and verifiable certifications have their own editors. A print-ready resume supports browser PDF export, a visible deployment-built snapshot, explicit updates when newer data is available, and usable offline and JavaScript-disabled views. Theme preferences carry across the professional experience without loading the desktop or games.'),
    (3, 'shortbits.net 2.0 - Blog and project publishing',
      'Added accessible Markdown blogging with drafts, live preview, authoring tools, image uploads, scheduled-post visibility, and public article pages. Deployment generates static articles, an RSS feed, sitemap entries, and a searchable archive. Admin compares saved posts with the deployed publishing snapshot, identifies pending additions, changes, and removals, and explains scheduled posts that need a later deployment. Added dedicated project pages and factual case studies for the homelab and this website.'),
    (4, 'shortbits.net 2.0 - Bits 365 Admin and content backups',
      'Rebuilt Admin as the Bits 365 admin center at /admin, with grouped navigation, hash-routed pages, search, account and appearance controls, dashboard counts, quick actions, and flyout editors. Added richer editors for career data, hardware, creators, music, and publishing. Content backups export 14 editorial tables, including drafts and creators, with schema validation, a pre-restore safety download, and atomic restoration. Private messages, credentials, telemetry, and image binaries remain excluded; older backup schemas are rejected explicitly.'),
    (5, 'shortbits.net 2.0 - ShortBits links and embeds',
      'Added an Admin-managed ShortBits link service with generated or custom aliases, HTTPS destinations, expiration, enable/disable controls, and aggregate click totals. ShortBits can redirect directly or use a masked landing page with supported YouTube, Vimeo, and Spotify embeds. Embed policy is integrated with deployment.'),
    (6, 'shortbits.net 2.0 - Hardware inventory and live agents',
      'Added HARDWARE.SYS with machine-grouped specs, Admin component editing, remembered collapse states, persistent device ordering, and cards that fill gaps below shorter lists. Read-only Windows PowerShell and Linux/Unraid Bash scans import reviewed specs; machine naming, renaming, and clash handling keep devices separate. Optional Windows agents use revocable tokens and encrypted local credentials, run without a visible console, sync specs, and report CPU/GPU/RAM usage, uptime, and LIVE/OFFLINE state. Watched machines update more frequently; live-agent chatter now accompanies real readings rather than simulated hardware values.'),
    (7, 'shortbits.net 2.0 - Unraid and NAS readings',
      'Added a privacy-filtered Unraid collector with its own device token and container build. HARDWARE.SYS can show array state, used/free storage, selected-LAN receive/transmit rates, drive status, and I/O errors alongside the machine inventory. NAS details collapse independently and stale readings are labeled explicitly. These readings are not Internet bandwidth measurements or a full SMART health assessment; hardware model descriptions remain manually reviewed rather than automatically imported.'),
    (8, 'shortbits.net 2.0 - CREATOR.FEED',
      'Added a creator-recommendation card and shareable CREATOR.FEED window. Admin manages names, platform labels, channel/profile links, notes, display order, and publication state for YouTube or other platforms. An optional YouTube UC channel ID enables the latest public-upload link without an API key; uploads can include Shorts and livestreams. Data loads only when the window opens, upload results are cached for up to ten minutes, and unavailable videos never remove the working channel links. Includes a refresh control and content-backup support.'),
    (9, 'shortbits.net 2.0 - BITS OS and CoBits',
      'Expanded BITS OS with desktop programs and shortcuts, an application-menu toolbar, window minimization, and resizing from every edge and corner. Added a desktop idle screensaver, a wandering DVD-style avatar, and rare corner-hit surprises. CoBits gained an animated avatar, quick actions, slash commands, conversational memory, multi-step interviews, diagnostics, delayed replies, and hidden discoveries. Action Center surprises, fictional network/VPN interactions, and additional malware and system-failure sequences deepen the desktop parody.'),
    (10, 'shortbits.net 2.0 - Arcade and favorite games',
      'Restored the desktop-only ARCADE.EXE and the Admin-curated favorite-games library after their 1.1 withdrawal. Available arcade games are Snake.BIT, Minesweeper, Bitsweeper, Bitris, Bit Pong, Packet Dodge, Cursor Chase, Null Tac Toe, Packet Breaker, and Flappy Bit. Packet Breaker now has endless waves, and Packet Dodge includes collection scoring. Local bests, public rankings, and Admin moderation accompany the games. BITITAIRE is temporarily unavailable for a rework; its implementation and saved scores are preserved.'),
    (11, 'shortbits.net 2.0 - Theme controls, variants, and layouts',
      'Expanded appearance beyond additional palettes: shared dark/light/theme-default modes, random theme selection, remembered per-theme variants, and grouped Standard Themes, Special Themes, and Experimental Layouts. Variants include Windows XP editions, RGB colorways, retro displays, browser spoofs, and console/firmware styles. Experimental layouts can reshape the interface into Windows, browser, music, office, search, or terminal experiences and load only when active. Themes gained distinct atmospheres, scrollbars, rounded form treatments, retro falling Bits, and classic crash-screen styling, while respecting motion, contrast, and performance preferences.'),
    (12, 'shortbits.net 2.0 - Seasonal messages and effects',
      'Expanded calendar-driven themes and transmissions for winter, Halloween, Christmas, New Year, Valentine''s Day, St. Patrick''s Day, Easter, Earth Day, Independence Day, and Thanksgiving. Added light/dark holiday palettes, overlap and priority rules, debug previews, and Independence Day binary-Bits fireworks. Additive holidays enrich rather than replace regular messages and activities, including boot logs, agent chatter, shutdown text, and desktop jokes; exclusive holiday behavior remains distinct. Effects honor reduced motion, high contrast, forced colors, and the effects-off preference.'),
    (13, 'shortbits.net 2.0 - Endless boot display',
      'Added the dedicated /boot display with shared themes and variants, randomized firmware logs, speed-sensitive bursts, long operations, themed transmissions, and rare warning/error/rainbow messages. Expanded it with correlated telemetry, POST codes, activity lights, unreliable countdowns, chained incidents and history, sparklines, uptime milestones, daily personalities, presence and connectivity reactions, idle degradation, local achievements, diagnostic/export commands, and self-recovering crash screens. Persistent fictional hardware, fullscreen and keyboard controls, compact display layouts, burn-in protection, drifting binary Bits, and themed power transitions support long-running displays.'),
    (14, 'shortbits.net 2.0 - Discovery, navigation, and notifications',
      'Added Find a Bit: a searchable launcher with keyboard navigation, accessible focus handling, and quick access to windows, pages, and actions. Shareable window URLs reopen linked windows and the desktop stays usable across viewport changes. NOTIFICATIONS.LOG keeps persistent history, unread counts, toast alerts, individual dismissal, and clear-all controls. A self-hosted source browser provides raw-file and archive access; recovery pages and deployment metadata make the running site easier to inspect.'),
    (15, 'shortbits.net 2.0 - Contact and live-service reliability',
      'Contact messages now use a protected Edge Function with honeypot, input/link limits, hashed rate limits, and optional Turnstile verification that loads near the form or on focus and can be retried. Optional Resend notifications and visitor confirmations run after a message is saved, so email failures do not lose the submission. Spotify and Discord integrations gained caching, coalesced refreshes, explicit stale/unavailable states, and timestamps; Spotify also honors upstream Retry-After cooldowns.'),
    (16, 'shortbits.net 2.0 - Performance, deployment, and monitoring',
      'Reduced blocking startup requests, generated smaller shared CSS, inlined first-paint styles, deferred full desktop styling and ordered enhancements safely, and lazy-loaded Arcade. Hidden clocks avoid unnecessary work; message layout and professional-page stability improved. Builds now version assets and generate compressed files and cache settings. Strict Lighthouse performance, accessibility, SEO, LCP, and CLS budgets remain enforced; specific browser/trace crashes get bounded retries, saved attempt reports, and N/A rather than false zero scores. Added production health monitoring, deployment/publishing consistency checks, and preserved startup traces for diagnosis.')
), last_position as (
  select coalesce(max(position), 0) as position from public.site_changelog
)
insert into public.site_changelog (position, entry_date, title, summary, enabled, updated_at)
select last_position.position + release_notes.ordinal, date '2026-10-25',
  release_notes.title, release_notes.summary, true, now()
from release_notes cross join last_position
order by release_notes.ordinal;
